const body = $json.body || $json;
const user_id = String(body.user_id || body.sender_id || body.from_id || '').trim();
const text = (body.text || body.message || '').trim();
const account_id = body.account_id || '';
const username = body.username || '';
const chat_id = Number(body.chat_id || body.user_id || 0);

if (!user_id || !text) {
  console.log('Skip: no user_id or text', JSON.stringify(body));
  return [];
}

return [{ json: { user_id, text, account_id, username, chat_id } }];

const allLeads = $input.all();
const incoming = $('Нормализуем данные').first().json;

const lead = allLeads.find(item =>
  String(item.json['UserID'] || '').trim() === String(incoming.user_id).trim()
);

if (!lead) {
  console.log('Лид не найден для user_id:', incoming.user_id);
  return [];
}

return [{
  json: {
    ...lead.json,
    user_id: incoming.user_id,
    incoming_text: incoming.text,
    account_id: incoming.account_id,
    chat_id: incoming.chat_id,
    username: incoming.username
  }
}];

const text = (typeof query === 'string' ? query : JSON.stringify(query)).trim();
if (!text) return 'Ошибка: пустой текст';

const ctx = $('Собираем контекст').first().json;
const account_id = ctx.account_id;
const chat_id = Number(ctx.chat_id);

if (!account_id || !chat_id) return 'Ошибка: нет account_id или chat_id';

const response = await $helpers.httpRequest({
  method: 'POST',
  url: 'http://localhost:8000/send',
  body: JSON.stringify({ account_id, chat_id, text }),
  headers: { 'Content-Type': 'application/json' }
});

return 'ok';

const CAL_API_KEY = 'ТВОЙ_CAL_API_KEY';
const EVENT_TYPE_ID = 'ТВОЙ_EVENT_TYPE_ID';

const start = new Date().toISOString();
const end = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

const response = await $helpers.httpRequest({
  method: 'GET',
  url: `https://api.cal.com/v2/slots/available?eventTypeId=${EVENT_TYPE_ID}&start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}`,
  headers: {
    Authorization: `Bearer ${CAL_API_KEY}`,
    'cal-api-version': '2024-09-04'
  }
});

const slots = response.data?.slots || {};
const lines = [];
for (const [date, times] of Object.entries(slots)) {
  for (const t of (Array.isArray(times) ? times : [])) {
    const dt = new Date(t.time || t);
    lines.push(`${dt.toLocaleDateString('ru-RU', {weekday:'short',day:'numeric',month:'long'})} ${dt.toLocaleTimeString('ru-RU', {hour:'2-digit',minute:'2-digit'})} (МСК)`);
  }
}

if (!lines.length) return 'Нет доступных слотов на ближайшие 7 дней';
return lines.slice(0, 8).join('\n');

const CAL_API_KEY = 'ТВОЙ_CAL_API_KEY';
const EVENT_TYPE_ID = 'ТВОЙ_EVENT_TYPE_ID';

let input = {};
try { input = JSON.parse(query); } catch(e) {
  return 'Ошибка: передай JSON {"start": "...", "name": "..."}';
}

if (!input.start || !input.name) return 'Ошибка: нужны поля start и name';

const response = await $helpers.httpRequest({
  method: 'POST',
  url: 'https://api.cal.com/v2/bookings',
  headers: {
    Authorization: `Bearer ${CAL_API_KEY}`,
    'cal-api-version': '2024-09-04',
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({
    eventTypeId: Number(EVENT_TYPE_ID),
    start: input.start,
    attendee: {
      name: input.name,
      email: 'telegram@placeholder.local',
      timeZone: 'Europe/Moscow',
      language: 'ru'
    }
  })
});

const booking = response.data || response;
return `Запись создана! ID: ${booking.id || booking.uid}. Время: ${input.start}`;
